#!/usr/bin/env python3
"""install_b5.py - land ruling B5 (spec change + amendment) in one atomic step.

Usage:
    python3 install_b5.py --repo /mnt/Code/visualstudio/Design-arch_multi-core
    python3 install_b5.py --repo <root> --dry-run

What it does, in order:
  1. backs up every file it is about to replace into <repo>/.b5_backup/<stamp>/
  2. writes all ten files (package, the 131-check gate, the landing verifier)
  3. verifies each written file by sha256
  4. runs the package gate   (python3 pd/v1/verify_patch_set.py --dir white_papers/final
                              --build-script pd/v1/build_diagrams_html.py)
  5. runs the landing verifier (python3 verify_landing.py --repo <repo>)

The files are coupled and must land together:
  - HLD_LLD_4x4_architecture.md + diagrams_rendered.html  (gate check S2c re-renders
    the HTML from the .md sources and compares byte-for-byte)
  - pd/v1/verify_patch_set.py + SLICE_16_1.md             (gate check J2 requires
    the slice to quote the count the gate actually runs)

Exit 0 = landed and green. Exit 1 = something failed; nothing is rolled back
(the backup directory holds the originals).
"""
