REQUIRED = [
    "white_papers/final/FINAL_whitepaper_v3.0.md",
    "white_papers/final/SPEC_SHEET.md",
    "white_papers/final/HLD_LLD_4x4_architecture.md",
    "white_papers/final/SLICE_16_1.md",
    "white_papers/final/diagrams_rendered.html",
    "pd/v1/verify_patch_set.py",
    "verify_landing.py",
]


def sha256(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=DEFAULT_REPO)
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()
    root = Path(args.repo).resolve()
    if not root.is_dir():
        print(f"ERROR: repo root not found: {root}")
        return 1

    stamp = time.strftime("%Y%m%d-%H%M%S")
    backup = root / ".b5_backup" / stamp
    print(f"repo:   {root}")
    print(f"backup: {backup}")
    print("-" * 78)

    # ---- 1/2/3: back up, write, verify -------------------------------------
    installed, already, problems = [], [], []
    for rel, (blob, want_sha) in sorted(PAYLOAD.items()):
        dest = root / rel
        data = zlib.decompress(base64.b64decode(blob))
        got = hashlib.sha256(data).hexdigest()
        if got != want_sha:
            problems.append(f"payload integrity failed for {rel}")
            continue
        if dest.is_file() and sha256(dest) == want_sha:
            already.append(rel)
            print(f"  [current] {rel}")
            continue
        if args.dry_run:
            print(f"  [would install] {rel} ({len(data)} bytes)")
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.is_file():
            backup.parent.mkdir(parents=True, exist_ok=True)
            b = backup / rel
            b.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(dest, b)
        dest.write_bytes(data)
        if sha256(dest) != want_sha:
            problems.append(f"write verification failed for {rel}")
            print(f"  [FAIL] {rel}")
            continue
        installed.append(rel)
        print(f"  [installed] {rel} ({len(data)} bytes)")

    if problems:
        print("-" * 78)
        for p in problems:
            print(f"  [FAIL] {p}")
        print("RESULT: FAIL - payload/install problem; see above.")
        return 1

    if args.dry_run:
        print("-" * 78)
        print("RESULT: dry run complete - nothing written.")
        return 0

    print(f"installed {len(installed)}, already current {len(already)}")
    print("-" * 78)

    # ---- 4: the package gate ------------------------------------------------
    gate = root / "pd/v1/verify_patch_set.py"
    gate_rc = None
    if gate.is_file():
        cmd = [sys.executable, str(gate), "--dir", "white_papers/final",
               "--build-script", "pd/v1/build_diagrams_html.py"]
        r = subprocess.run(cmd, cwd=root, capture_output=True, text=True)
        gate_rc = r.returncode
        for line in (r.stdout or "").splitlines()[:1]:
            print(f"package gate: {line}")
        if r.returncode != 0:
            for line in (r.stdout or "").splitlines():
                if line.startswith("[FAIL]"):
                    print(f"  {line.strip()[:170]}")
    else:
        print("package gate: NOT FOUND (pd/v1/verify_patch_set.py)")

    # ---- 5: the landing verifier --------------------------------------------
    land = root / "verify_landing.py"
    land_rc = None
    if land.is_file():
        r = subprocess.run([sys.executable, str(land), "--repo", str(root)],
                           capture_output=True, text=True)
        land_rc = r.returncode
        for line in (r.stdout or "").splitlines():
            if line.startswith("RESULT:"):
                print(f"landing:     {line}")
            elif line.startswith("  [FAIL]"):
                print(f"  {line.strip()[:170]}")
    else:
        print("landing:     NOT FOUND (verify_landing.py)")

    print("-" * 78)
    ok = (gate_rc == 0 and land_rc == 0)
    if ok:
        print("RESULT: PASS - the amended package is landed and the package gate is green.")
        print("The spec package is current. The implementation is NOT: ruling B6 (the same-line")
        print("INV abort, section 16.15) must be implemented in the RTL, modelled, asserted and")
        print("mutation-tested before the package can be signed off.")
        if installed:
            print(f"Originals of the {len(installed)} replaced file(s) are in {backup}")
    else:
        print(f"RESULT: FAIL - package gate exit {gate_rc}, landing exit {land_rc}.")
        print("Do not start Task 0. Paste the output above.")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
